<x-app-layout> <x-slot name="header"> <div class="flex justify-between items-center"> <div> <h2 class="font-semibold text-xl text-gray-800 leading-tight"> Mi horario </h2> <p class="text-sm text-gray-500 mt-1"> Configure los días y horas en los que estará disponible para atender citas. </p> </div> <a href="{{ route('staff.dashboard') }}" class="px-4 py-2 bg-gray-600 text-white rounded-md hover:bg-gray-700 transition" > Volver al Dashboard </a> </div> </x-slot> <div class="py-8"> <div class="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8"> <!-- MENSAJE DE ÉXITO --> @if (session('success')) <div class="mb-6 p-4 bg-green-100 border border-green-300 text-green-800 rounded-md"> {{ session('success') }} </div> @endif <!-- ERRORES --> @if ($errors->any()) <div class="mb-6 p-4 bg-red-100 border border-red-300 text-red-800 rounded-md"> <p class="font-semibold mb-2"> Revise los siguientes errores: </p> <ul class="list-disc pl-5"> @foreach ($errors->all() as $error) <li> {{ $error }} </li> @endforeach </ul> </div> @endif <!-- TARJETA --> <div class="bg-white overflow-hidden shadow-sm sm:rounded-lg"> <div class="p-6 text-gray-900"> <div class="mb-6"> <h3 class="text-lg font-semibold text-gray-800"> Horario semanal </h3> <p class="text-sm text-gray-500 mt-1"> Active los días que trabaja y establezca su hora de entrada y salida. </p> </div> <form method="POST" action="{{ route('staff.schedule.update') }}" > @csrf @method('PUT') <div class="space-y-4"> @php $days = [ 0 => 'Domingo', 1 => 'Lunes', 2 => 'Martes', 3 => 'Miércoles', 4 => 'Jueves', 5 => 'Viernes', 6 => 'Sábado', ]; @endphp @foreach ($days as $dayNumber => $dayName) @php $schedule = $schedules ->where('day_of_week', $dayNumber) ->first(); $isActive = $schedule ? $schedule->is_active : false; $startTime = $schedule ? substr($schedule->start_time, 0, 5) : '08:00'; $endTime = $schedule ? substr($schedule->end_time, 0, 5) : '17:00'; @endphp <div class="border border-gray-200 rounded-lg p-4" x-data="{ active: {{ $isActive ? 'true' : 'false' }} }" > <input type="hidden" name="schedule[{{ $dayNumber }}][day_of_week]" value="{{ $dayNumber }}" > <div class="grid grid-cols-1 md:grid-cols-4 gap-4 items-center"> <!-- DÍA --> <div> <label class="flex items-center"> <input type="checkbox" name="schedule[{{ $dayNumber }}][is_active]" value="1" x-model="active" class="rounded border-gray-300 text-indigo-600 shadow-sm focus:ring-indigo-500" > <span class="ml-3 font-semibold text-gray-800"> {{ $dayName }} </span> </label> </div> <!-- HORA INICIO --> <div> <label class="block text-sm font-medium text-gray-700 mb-1" > Entrada </label> <input type="time" name="schedule[{{ $dayNumber }}][start_time]" value="{{ old("schedule.$dayNumber.start_time", $startTime) }}" x-bind:disabled="!active" class="w-full border-gray-300 rounded-md shadow-sm focus:border-indigo-500 focus:ring-indigo-500 disabled:bg-gray-100 disabled:text-gray-400" > </div> <!-- HORA FIN --> <div> <label class="block text-sm font-medium text-gray-700 mb-1" > Salida </label> <input type="time" name="schedule[{{ $dayNumber }}][end_time]" value="{{ old("schedule.$dayNumber.end_time", $endTime) }}" x-bind:disabled="!active" class="w-full border-gray-300 rounded-md shadow-sm focus:border-indigo-500 focus:ring-indigo-500 disabled:bg-gray-100 disabled:text-gray-400" > </div> <!-- ESTADO --> <div class="text-sm"> <span x-show="active" class="inline-flex px-3 py-1 rounded-full bg-green-100 text-green-700 font-medium" > Trabaja </span> <span x-show="!active" class="inline-flex px-3 py-1 rounded-full bg-gray-100 text-gray-600 font-medium" > No trabaja </span> </div> </div> </div> @endforeach </div> <!-- BOTÓN --> <div class="mt-8 flex justify-end"> <button type="submit" class="px-6 py-3 bg-indigo-600 text-white font-semibold rounded-md hover:bg-indigo-700 transition shadow-sm" > Guardar horario </button> </div> </form> </div> </div> <!-- INFORMACIÓN --> <div class="mt-6 p-4 bg-blue-50 border border-blue-200 rounded-lg"> <p class="text-sm text-blue-800"> <strong>Importante:</strong> Los horarios que configure aquí serán utilizados posteriormente para determinar los días y horas disponibles para que los clientes puedan reservar una cita con usted. </p> </div> </div> </div> </x-app-layout>